1	//! Enforcement test: outside `callisto-model` and
2	//! `callisto-manifests`, no crate should hand-parse `Cargo.toml`/
3	//! `package.json`/`pyproject.toml` (i.e. reference one of those file names
4	//! as a raw string literal *and* independently invoke a raw TOML/JSON
5	//! parse in the same file) instead of going through the shared readers in
6	//! `callisto_manifests` (`cargo_package_name`/`npm_package_name`/
7	//! `python_package_name`, `read_identity`, `read_napi_targets`).
8	//!
9	//! This is a coarse, file-level, production-code-only grep -- a regression
10	//! tripwire against *new* hand-parsing, not a precise static analyzer. Test
11	//! modules (`#[cfg(test)] mod ...`) are stripped before checking, since
12	//! test fixtures legitimately write out manifest files with these names.
13	//!
14	//! A handful of files are allowlisted below because they parse these
15	//! manifests for a genuinely different purpose than package-identity
16	//! (name/version) extraction -- see each entry's reason.
17	
18	use std::fs;
19	use std::path::PathBuf;
20	
21	mod common;
22	use common::{collect_rust_src_files, strip_test_modules, workspace_root};
23	
24	/// Files allowed to contain a manifest-filename literal alongside a raw
25	/// parse call in production code, and why. Paths are relative to the
26	/// workspace root, forward-slash separated.
27	const ALLOWLIST: &[(&str, &str)] = &[
28	    (
29	        "crates/callisto-graph/src/locate/root.rs",
30	        "workspace-root marker detection (`[workspace]` / `workspaces` field presence), \
31	         not package identity extraction",
32	    ),
33	    (
34	        "crates/callisto-graph/src/locate/membership.rs",
35	        "workspace membership (members/exclude/workspaces glob) parsing, not package identity \
36	         extraction; already routes canonical manifest file names through \
37	         `ManifestFormat::*.file_name()` (audit pattern B, item 3)",
38	    ),
39	    (
40	        "crates/callisto-graph/src/napi.rs",
41	        "parses package.json into a serde_json::Value only to hand to the shared \
42	         callisto_manifests::read_napi_targets -- the field-extraction logic itself lives in \
43	         callisto-manifests, not here",
44	    ),
45	    (
46	        "crates/callisto-graph/src/matrix.rs",
47	        "parses package.json/pyproject.toml generically to extract non-identity fields \
48	         (engines.node, requires-python, [tool.maturin]); napi.targets extraction itself is \
49	         delegated to the shared callisto_manifests::read_napi_targets",
50	    ),
51	    (
52	        "crates/callisto-graph/src/commands/release_decision.rs",
53	        "the serde_json parse decodes the committed release decision; historical manifest blobs \
54	         are parsed by callisto_manifests::read_effective_version",
55	    ),
56	];
57	
58	const MANIFEST_LITERALS: [&str; 3] = ["\"Cargo.toml\"", "\"package.json\"", "\"pyproject.toml\""];
59	const PARSE_MARKERS: [&str; 3] = ["toml_edit::Document", "serde_json::from_str", ".parse::<toml_edit"];
60	
61	#[test]
62	fn no_hand_rolled_manifest_parsing_outside_model_and_manifests_crates() {
63	    let root = workspace_root();
64	    let crates_dir = root.join("crates");
65	
66	    let crate_dirs = fs::read_dir(&crates_dir)
67	        .unwrap_or_else(|e| panic!("could not read workspace crates dir at {crates_dir:?}: {e}"));
68	
69	    let mut violations = Vec::new();
70	
71	    for entry in crate_dirs.flatten() {
72	        let crate_path = entry.path();
73	        if !crate_path.is_dir() {
74	            continue;
75	        }
76	        let crate_name = crate_path.file_name().and_then(|n| n.to_str()).unwrap_or_default();
77	        if crate_name == "callisto-model" || crate_name == "callisto-manifests" {
78	            continue;
79	        }
80	
81	        let src_dir = crate_path.join("src");
82	        if !src_dir.is_dir() {
83	            continue;
84	        }
85	
86	        let mut files = Vec::new();
87	        collect_rust_src_files(&src_dir, &mut files);
88	
89	        for file in files {
90	            let Ok(content) = fs::read_to_string(&file) else {
91	                continue;
92	            };
93	            let production = strip_test_modules(&content);
94	
95	            let has_manifest_literal = MANIFEST_LITERALS.iter().any(|lit| production.contains(lit));
96	            let has_raw_parse = PARSE_MARKERS.iter().any(|marker| production.contains(marker));
97	
98	            if has_manifest_literal && has_raw_parse {
99	                let rel = file
100	                    .strip_prefix(&root)
101	                    .unwrap_or(&file)
102	                    .to_string_lossy()
103	                    .replace('\\', "/");
104	                if !ALLOWLIST.iter().any(|(path, _reason)| *path == rel) {
105	                    violations.push(rel);
106	                }
107	            }
108	        }
109	    }
110	
111	    assert!(
112	        violations.is_empty(),
113	        "found hand-rolled manifest parsing outside callisto-model/callisto-manifests (a \
114	         Cargo.toml/package.json/pyproject.toml literal alongside a raw toml_edit/serde_json \
115	         parse call) in production code -- route through callisto_manifests::{{cargo_package_name, \
116	         npm_package_name, python_package_name, read_identity, read_napi_targets}} instead, or add \
117	         a justified entry to this test's ALLOWLIST: {violations:#?}"
118	    );
119	}
120	
121	/// Keeps the allowlist honest: an entry naming a missing file
122	/// (renamed, deleted, or fully migrated) should be removed, not silently
123	/// carried forward.
124	#[test]
125	fn allowlist_entries_reference_files_that_still_exist() {
126	    let root = workspace_root();
127	    for (path, _reason) in ALLOWLIST {
128	        assert!(
129	            root.join(path).exists(),
130	            "allowlisted path no longer exists, remove this entry: {path}"
131	        );
132	    }
133	}
134	
135	// --- Typed release errors ------------------------------------------------
136	// Enforcement for the `GraphError::ReleaseIntentStale` (E124) struct variant: staleness carries a real
137	// `StaleReason`, constructible only from the `commands/release/` module (`StaleReason` itself lives in its `mod.rs`).
138	
139	/// This crate's own `src/` directory, independent of `workspace_root()`
140	/// (which points at the whole-workspace root two levels up).
141	fn graph_crate_src_dir() -> PathBuf {
142	    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("src")
143	}
144	
145	/// Reads `relative` (forward-slash separated, relative to this crate's
146	/// `src/`, e.g. `"commands/release/mod.rs"`) with `#[cfg(test)] mod tests { ... }`
147	/// blocks stripped.
148	fn read_production_source(relative: &str) -> String {
149	    let path = graph_crate_src_dir().join(relative);
150	    let content = fs::read_to_string(&path).unwrap_or_else(|e| panic!("could not read {path:?}: {e}"));
151	    strip_test_modules(&content)
152	}
153	
154	/// `StaleReason`'s four fresh-re-observation constructors.
155	const STALE_REASON_REAL_CONSTRUCTORS: [&str; 4] = [
156	    "trust_evidence_changed",
157	    "source_identity_changed",
158	    "git_remote_changed",
159	    "intent_differs_from_fresh_derivation",
160	];
161	
162	/// `GraphError::ReleaseIntentStale` is constructed only via one of
163	/// `StaleReason`'s four fresh-re-observation constructors, and only from
164	/// the `commands/release/` module; no other construction site exists workspace-wide.
165	#[test]
166	fn release_intent_stale_is_constructed_only_by_fresh_reobservation() {
167	    let release_module = graph_crate_src_dir().join("commands/release");
168	    let mut files = Vec::new();
169	    collect_rust_src_files(&graph_crate_src_dir(), &mut files);
170	
171	    let mut violations = Vec::new();
172	    for file in files {
173	        if file.starts_with(&release_module) {
174	            continue;
175	        }
176	        let Ok(content) = fs::read_to_string(&file) else {
177	            continue;
178	        };
179	        let production = strip_test_modules(&content);
180	        for name in STALE_REASON_REAL_CONSTRUCTORS {
181	            if production.contains(name) {
182	                violations.push(format!("{}: references `{name}`", file.display()));
183	            }
184	        }
185	    }
186	
187	    assert!(
188	        violations.is_empty(),
189	        "StaleReason's fresh-re-observation constructors must be referenced only from \
190	         the commands/release/ module: {violations:#?}"
191	    );
192	}
193	
194	/// The four real constructors carry no visibility modifier --
195	/// callable only from within the `commands/release/` module itself.
196	#[test]
197	fn stale_reason_constructors_are_module_private() {
198	    let production = read_production_source("commands/release/mod.rs");
199	
200	    let mut violations = Vec::new();
201	    for name in STALE_REASON_REAL_CONSTRUCTORS {
202	        let needle = format!("fn {name}");
203	        for line in production.lines() {
204	            if line.contains(&needle) && line.contains("pub") {
205	                violations.push(format!("`{name}` has a visibility modifier: {}", line.trim()));
206	            }
207	        }
208	    }
209	
210	    assert!(
211	        violations.is_empty(),
212	        "StaleReason's real constructors must carry no pub/pub(crate)/pub(super) visibility: {violations:#?}"
213	    );
214	}
215	
216	/// Files still permitted to discard their `map_err` closure's bound error.
217	/// The release-executor files are not allowlisted. The remaining five
218	/// predate this check and are not migrated yet.
219	///
220	/// This test's job is to block a new file from adopting the pattern, not to
221	/// re-litigate already-tracked ones.
222	const MAP_ERR_IGNORE_ALLOWLIST: &[&str] = &[
223	    "locate/ignore_walk.rs",
224	    "config/resolve.rs",
225	    "cascade.rs",
226	    "commands/publish.rs",
227	    "commands/snapshot.rs",
228	];
229	
230	/// True if `content` contains a `map_err(|_ident| ...)` closure -- one whose
231	/// bound error parameter is never used, evading `clippy::map_err_ignore`
232	/// (which only matches the bare `|_|` spelling).
233	fn contains_map_err_ignore(content: &str) -> bool {
234	    let marker = "map_err(|_";
235	    let mut search_from = 0;
236	    while let Some(relative_pos) = content[search_from..].find(marker) {
237	        // `marker` itself ends in the closure parameter's leading `_`.
238	        let ident_start = search_from + relative_pos + marker.len() - 1;
239	        let rest = &content[ident_start..];
240	        let ident_len = rest
241	            .char_indices()
242	            .take_while(|(_, c)| c.is_alphanumeric() || *c == '_')
243	            .count();
244	        if rest[ident_len..].starts_with('|') {
245	            return true;
246	        }
247	        search_from = ident_start + ident_len.max(1);
248	    }
249	    false
250	}
251	
252	/// Zero `map_err(|_ident| ...)` source-discarding closures anywhere
253	/// in this crate except the allowlisted, pre-existing files; this test fails on any
254	/// non-allowlisted file adopting the pattern.
255	#[test]
256	fn release_modules_never_discard_error_sources() {
257	    let src_dir = graph_crate_src_dir();
258	    let mut files = Vec::new();
259	    collect_rust_src_files(&src_dir, &mut files);
260	
261	    let mut violations = Vec::new();
262	    for file in files {
263	        let Ok(content) = fs::read_to_string(&file) else {
264	            continue;
265	        };
266	        let production = strip_test_modules(&content);
267	        if !contains_map_err_ignore(&production) {
268	            continue;
269	        }
270	        let relative = file
271	            .strip_prefix(&src_dir)
272	            .unwrap_or(&file)
273	            .to_string_lossy()
274	            .replace('\\', "/");
275	        if !MAP_ERR_IGNORE_ALLOWLIST.contains(&relative.as_str()) {
276	            violations.push(relative);
277	        }
278	    }
279	
280	    assert!(
281	        violations.is_empty(),
282	        "found a new map_err(|_ident| ...) source-discarding closure outside the \
283	         allowlist ({MAP_ERR_IGNORE_ALLOWLIST:?}); report the real error cause instead: {violations:#?}"
284	    );
285	}
286	
287	/// True if `content` grants an `ApplyPermit` from a literal `true`/`false` instead of the
288	/// parsed `--dry-run` flag, ignoring whitespace so a reformatted call is still caught.
289	fn grants_permit_from_literal(content: &str) -> bool {
290	    let compact: String = content.split_whitespace().collect();
291	    ["true", "false"].iter().any(|literal| {
292	        compact.contains(&format!("granted_unless_dry_run({literal})"))
293	            || compact.contains(&format!("granted_unless_dry_run({literal},)"))
294	    })
295	}
296	
297	/// `ApplyPermit::granted_unless_dry_run` must take the parsed flag read once near the top of a
298	/// handler. A literal re-derives the decision and can silently disagree with `--dry-run`.
299	#[test]
300	fn apply_permits_are_never_granted_from_a_literal() {
301	    let root = workspace_root();
302	    let mut violations = Vec::new();
303	    for entry in fs::read_dir(root.join("crates")).unwrap().flatten() {
304	        let src_dir = entry.path().join("src");
305	        if !src_dir.is_dir() {
306	            continue;
307	        }
308	        let mut files = Vec::new();
309	        collect_rust_src_files(&src_dir, &mut files);
310	        for file in files {
311	            if file.file_name().and_then(|n| n.to_str()) == Some("permit.rs") {
312	                continue;
313	            }
314	            let Ok(content) = fs::read_to_string(&file) else {
315	                continue;
316	            };
317	            if grants_permit_from_literal(&strip_test_modules(&content)) {
318	                violations.push(file.strip_prefix(&root).unwrap_or(&file).to_string_lossy().into_owned());
319	            }
320	        }
321	    }
322	    assert!(
323	        violations.is_empty(),
324	        "pass the parsed dry-run flag to ApplyPermit::granted_unless_dry_run, never a literal: {violations:#?}"
325	    );
326	}
327	
328	#[test]
329	fn literal_permit_detector_catches_a_reformatted_call_and_ignores_the_flag() {
330	    assert!(grants_permit_from_literal("ApplyPermit::granted_unless_dry_run(false)"));
331	    assert!(grants_permit_from_literal(
332	        "ApplyPermit::granted_unless_dry_run(\n    true,\n)"
333	    ));
334	    assert!(!grants_permit_from_literal(
335	        "ApplyPermit::granted_unless_dry_run(global.dry_run)"
336	    ));
337	}
